// Beginner walkthroughs for the original 30-pin ESP32 DevKit V1.
// Targets describe semantic parts and pins, not breadboard hole coordinates.
// `connection` refers to a zero-based lesson.wiring row; several steps may
// explain different details of the same connection.
const step = (id, title, text, targets, view = 'connection', connection) => ({
  id, title, text, targets, view,
  ...(Number.isInteger(connection) ? { connection } : {})
});

export const guides = {
  board: [
    step('board-usb', 'Start at the USB socket', 'This small socket accepts a Micro-USB cable. The cable brings power from your computer and carries program uploads and messages. Use a data-capable cable: some charging cables supply power but cannot send a sketch.', ['part:usb'], 'usb', 0),
    step('board-ground', 'GND is the shared zero', 'GND means ground: the circuit’s common 0 V reference and return path. Connect a component’s ground to a GND pin so it and the ESP32 agree on what “zero volts” means. It is not the same as a signal pin.', ['pin:GND'], 'board', 1),
    step('board-power', '3V3 supplies small components', '3V3 means 3.3 volts. This power pin supplies suitable low-power sensors; it does not change when your program calls digitalWrite(). The regulator makes this rail from USB power. GPIO inputs also use 3.3 V logic, but they are separate pins and cannot accept 5 V.', ['pin:3V3', 'part:regulator'], 'board', 2),
    step('board-signal', 'A numbered GPIO carries a signal', 'GPIO means general-purpose input/output. A sketch can read a GPIO or control it: HIGH is about 3.3 V and LOW is about 0 V, measured from GND. “GPIO23” means the pin labeled 23, not the twenty-third header position.', ['pin:23', 'part:module', 'pin:GND'], 'board')
  ],
  blink: [
    step('blink-output', 'Find GPIO23 and the resistor', 'GPIO23 is the controlled output. Connect it through a 330 Ω resistor to the LED’s positive leg, called the anode. The resistor limits current; an LED must not be connected straight across an output and ground without current limiting.', ['pin:23', 'component:resistor:330', 'component:led'], 'connection', 0),
    step('blink-return', 'Give the LED a return path', 'Connect the LED’s negative leg, the cathode, to GND. It is usually the shorter leg beside the flat edge of the LED body. Ground completes the path back to the board; reversing the LED usually leaves it dark.', ['component:led', 'pin:GND'], 'connection', 1),
    step('blink-cycle', 'Follow one complete blink', 'Start the simulation and tap the LED to change timing. HIGH on GPIO23 lights it; LOW turns it off. One complete blink includes both the on-time and the off-time. The series resistor stays in the circuit throughout.', ['pin:23', 'component:led', 'component:resistor:330', 'pin:GND'], 'circuit')
  ],
  button: [
    step('button-input', 'Use GPIO18 as the input', 'Connect GPIO18 to one switched side of the button. INPUT_PULLUP in the sketch gives the released input a steady HIGH value. That internal pull-up replaces a separate resistor for this particular button circuit.', ['pin:18', 'component:button'], 'connection', 0),
    step('button-ground', 'The press connects to ground', 'Connect the other switched side to GND. Pressing the button joins GPIO18 to ground, so the input reads LOW. On many four-leg buttons, two legs on the same side are already joined; choose contacts that connect only when pressed.', ['component:button', 'pin:GND'], 'connection', 1),
    step('button-indicator', 'Use a separate output for the LED', 'GPIO23 drives the indicator through a 330 Ω resistor. The LED’s cathode returns to GND. GPIO18 reads the button; GPIO23 controls the light. The sketch links these two jobs with the pressed condition.', ['pin:23', 'component:resistor:330', 'component:led', 'pin:GND'], 'connection', 2),
    step('button-try', 'Hold, then release', 'Start the simulation and hold the button. Watch the input become LOW while the LED turns on. Releasing restores HIGH and turns the LED off. LOW describes the electrical level; “pressed” describes what that level means in this wiring.', ['component:button', 'component:led', 'pin:18'], 'circuit')
  ],
  potentiometer: [
    step('pot-power', 'Power the two outside terminals', 'Connect one outer terminal of the potentiometer to 3V3 and the other to GND. These are the two ends of its resistive track. Use 3.3 V here, because the center terminal will feed an ESP32 input.', ['pin:3V3', 'pin:GND', 'component:potentiometer'], 'connection', 0),
    step('pot-wiper', 'Read the middle terminal', 'The middle terminal is the wiper: turning the knob changes its voltage between the two ends. Connect it to GPIO34. The analog-to-digital converter, or ADC, turns this changing voltage into a number. GPIO34 is input-only and cannot drive an LED.', ['component:potentiometer', 'pin:34'], 'connection', 1),
    step('pot-output', 'Send the result to an LED', 'Connect GPIO23 through 330 Ω and an LED to GND. Pulse-width modulation, or PWM, switches this output quickly on and off. Duty cycle means the fraction of time spent on. The sketch maps the input number to this fraction, making the LED brighter or dimmer.', ['pin:23', 'component:resistor:330', 'component:led', 'pin:GND'], 'connection', 2),
    step('pot-try', 'Turn position into brightness', 'Start the simulation and drag the knob. Follow the chain: knob position changes voltage, the ADC turns voltage into a number, and PWM turns the number into brightness. Real ADC readings have noise and may reach their limit before 3.3 V.', ['component:potentiometer', 'pin:34', 'component:led'], 'circuit')
  ],
  rgb: [
    step('rgb-red', 'Give red its own path', 'Connect GPIO25 through a 330 Ω resistor to the red anode of a common-cathode RGB LED. An RGB package contains three emitters. Check its datasheet for the lead order; the shape alone does not tell you which lead is red.', ['pin:25', 'component:resistor:330', 'component:rgb'], 'connection', 0),
    step('rgb-green', 'Add the green channel', 'Connect GPIO26 through a second 330 Ω resistor to the green anode. Each color needs its own resistor because the emitters have different electrical characteristics. The program can change this channel independently of red.', ['pin:26', 'component:resistor:330', 'component:rgb'], 'connection', 1),
    step('rgb-blue', 'Add the blue channel', 'Connect GPIO27 through a third 330 Ω resistor to the blue anode. The sketch calculates three brightness values from the chosen hue. A hue angle is a color choice; it is not a voltage sent to a single pin.', ['pin:27', 'component:resistor:330', 'component:rgb'], 'connection', 2),
    step('rgb-ground', 'Join the common cathode to GND', 'The common cathode is the shared negative connection of all three emitters. Connect it to GND. This guide assumes a common-cathode part; a common-anode LED requires different wiring and inverted brightness control.', ['component:rgb', 'pin:GND'], 'connection', 3),
    step('rgb-try', 'Mix the three lights', 'Run the simulation and tap the RGB LED to change color, or drag to sweep the hue. Red and green light can combine to look yellow. The visible color comes from three separate current paths working together.', ['component:rgb', 'pin:25', 'pin:26', 'pin:27'], 'circuit')
  ],
  light: [
    step('light-upper', 'Start the divider at 3V3', 'Connect the light-dependent resistor, or LDR, between 3V3 and the GPIO34 junction. Its resistance falls in brighter light. The 3V3 pin supplies the divider; GPIO34 only measures the voltage at its middle.', ['pin:3V3', 'component:ldr', 'pin:34'], 'connection', 0),
    step('light-lower', 'Complete the divider to ground', 'Connect a 10 kΩ resistor from the GPIO34 junction to GND. The LDR and this fixed resistor divide the supply voltage. With this arrangement, brighter light raises the measured voltage and covering the sensor lowers it.', ['pin:34', 'component:resistor:10k', 'pin:GND'], 'connection', 1),
    step('light-output', 'Connect the night-light output', 'GPIO23 drives an LED through a separate 330 Ω resistor to GND. Do not confuse this current-limiting resistor with the 10 kΩ sensor resistor. The sketch turns the LED on when the light reading falls below its threshold.', ['pin:23', 'component:led', 'component:resistor:330', 'pin:GND'], 'connection', 2),
    step('light-try', 'Cover the sensor', 'Run the simulation, then hold the LDR to cover it. The input falls and the night-light turns on. Release to restore the ambient light. A real circuit needs a threshold chosen from readings in its actual surroundings.', ['component:ldr', 'component:led', 'pin:34'], 'circuit')
  ],
  distance: [
    step('distance-power', 'Power the sensor at its rated voltage', 'A standard HC-SR04 needs 5 V at VCC and ground at GND. Use a suitable 5 V supply and join its ground to ESP32 GND. The sensor’s 5 V power requirement does not make the ESP32’s GPIO pins 5 V tolerant.', ['component:distance', 'component:supply', 'pin:GND'], 'connection', 0),
    step('distance-trigger', 'Send a trigger from GPIO23', 'Connect GPIO23 to Trig. A short pulse asks the sensor to send ultrasound. Most HC-SR04 modules accept this 3.3 V trigger; check the module specification if yours does not respond.', ['pin:23', 'component:distance'], 'connection', 1),
    step('distance-echo', 'Reduce the Echo signal first', 'The Echo terminal can output 5 V, so do not connect it directly to GPIO34. Put a 2.2 kΩ resistor between Echo and the GPIO34 junction. This is the upper half of a two-resistor voltage divider.', ['component:distance', 'component:resistor:2.2k', 'pin:34'], 'connection', 2),
    step('distance-divider', 'Finish the protective divider', 'Connect 3.3 kΩ from the GPIO34 junction to GND. Together, the two resistors reduce a 5 V Echo to about 3 V. GPIO34 reads that safe signal; it is input-only and cannot generate the trigger.', ['pin:34', 'component:resistor:3.3k', 'pin:GND'], 'connection', 3),
    step('distance-try', 'Move the obstacle', 'Run the simulation and drag the obstacle closer or farther away. A real sensor measures the sound’s round-trip time, then divides the travel distance by two. No returned echo is a missing measurement, not proof that the distance is zero.', ['component:distance'], 'circuit')
  ],
  sound: [
    step('sound-signal', 'Drive a small passive piezo', 'Connect GPIO25 through 100 Ω to the positive terminal of a small passive piezo. The changing output makes it vibrate. This example is not a direct-drive circuit for a low-impedance speaker or a high-current buzzer.', ['pin:25', 'component:resistor:100', 'component:buzzer'], 'connection', 0),
    step('sound-return', 'Connect its negative side to GND', 'The other piezo terminal returns to GND, completing the signal’s electrical path. Use a passive piezo for selectable notes. An active buzzer includes its own oscillator and often produces a fixed pitch when powered.', ['component:buzzer', 'pin:GND'], 'connection', 1),
    step('sound-try', 'Hear frequency become pitch', 'Enable Sound, run the simulation and tap or drag the piezo to change frequency. A higher frequency sounds higher; doubling 440 Hz to 880 Hz raises the pitch by an octave. Passing zero to ledcWriteTone() stops a real tone.', ['component:buzzer', 'pin:25'], 'circuit')
  ],
  piano: [
    step('piano-first', 'Connect the first four keys', 'Connect buttons C, D, E and F between GPIO13, GPIO14, GPIO16 and GPIO17 respectively and GND. Each input uses INPUT_PULLUP, so holding a key makes it read LOW. On this board, GPIO16 and GPIO17 may be labeled RX2 and TX2.', ['pin:13', 'pin:14', 'pin:16', 'pin:17', 'pin:GND', 'component:piano'], 'connection', 0),
    step('piano-second', 'Give the other keys separate inputs', 'Connect G, A, B and the higher C to GPIO18, GPIO19, GPIO21 and GPIO22, each through its own button to GND. The ground is shared, but the eight signal inputs remain separate so the sketch can identify the selected key.', ['pin:18', 'pin:19', 'pin:21', 'pin:22', 'pin:GND', 'component:piano'], 'connection', 1),
    step('piano-output', 'Share one sound output', 'Connect GPIO25 through 100 Ω to a small passive piezo, then connect its other terminal to GND. All keys choose the frequency of this one output. The example plays one note at a time rather than giving each key its own buzzer.', ['pin:25', 'component:resistor:100', 'component:buzzer', 'pin:GND'], 'connection', 2),
    step('piano-try', 'Hold a key and listen', 'Enable Sound and run the simulation. Hold a 3D piano key, then release it. The notes array maps each input to a frequency; releasing the key returns the output to silence. The first and last C are one octave apart.', ['component:piano', 'component:buzzer'], 'circuit')
  ],
  motor: [
    step('motor-gate', 'Send control to the transistor', 'GPIO25 connects through 100 Ω to G, the MOSFET’s gate or control terminal. Add 10 kΩ from G to ground so it stays off when not driven. The worked example uses an AO3400A breakout with labeled G/D/S terminals, suitable for a 3.3 V gate signal.', ['pin:25', 'component:driver', 'component:resistor:100', 'component:resistor:10k', 'pin:GND'], 'connection', 0),
    step('motor-ground', 'Share the ground reference', 'Connect S, the MOSFET source, to the motor supply’s ground and ESP32 GND. The gate signal is measured from this same zero-volt reference. The motor’s large current should return through its power wiring, not through a GPIO pin.', ['component:driver', 'component:supply', 'pin:GND'], 'connection', 1),
    step('motor-drain', 'Let the transistor switch the motor', 'Connect motor negative to D, the MOSFET drain. The transistor completes or interrupts this current path. Follow the breakout labels and the manufacturer’s pinout drawing, including its viewing direction; gate, drain and source positions differ between packages.', ['component:motor', 'component:driver'], 'connection', 2),
    step('motor-supply', 'Supply motor power separately', 'Connect motor positive to a supply matched to its voltage and starting current. The worked example uses a 3 V motor with specified stall current at most 300 mA and a 2×AA holder, about 3 V. The ESP32 stays USB-powered. Never power the motor from GPIO25 or 3V3.', ['component:motor', 'component:supply'], 'connection', 3),
    step('motor-diode', 'Give stored current a safe path', 'Place the flyback diode across the motor. On the example’s 1N5819, the band marks the cathode: connect that end to motor positive and the other end to D. It handles winding current after switch-off. Then run the simulation and drag the motor to explore duty cycle.', ['component:diode', 'component:motor', 'component:driver'], 'connection', 3)
  ],
  temperature: [
    step('temperature-power', 'Power the sensor from 3V3', 'Connect the DHT22 supply terminal, usually called VCC, to 3V3. VCC means the sensor’s positive power connection. Check the pinout of your bare sensor or breakout module; its terminal order may differ from another version.', ['pin:3V3', 'component:temperature'], 'connection', 0),
    step('temperature-data', 'Give its data line a resting level', 'Connect DHT22 data to GPIO27. A bare sensor also needs a 10 kΩ pull-up from data to 3V3; some modules include it. This pin carries digital messages, not an analog voltage proportional to temperature.', ['pin:27', 'pin:3V3', 'component:resistor:10k', 'component:temperature'], 'connection', 1),
    step('temperature-ground', 'Connect the sensor’s ground', 'Join the DHT22 GND terminal to ESP32 GND so the power and data share a zero-volt reference. On a bare four-pin DHT22, the unused terminal is not a substitute for GND. Follow its datasheet.', ['component:temperature', 'pin:GND'], 'connection', 2),
    step('temperature-try', 'Change the surrounding temperature', 'Run the simulation and drag the sensor to explore warmer or cooler conditions. The browser changes a model value. A real DHT22 responds more slowly and should be read at least two seconds apart; failed reads must be handled separately.', ['component:temperature', 'pin:27'], 'circuit')
  ],
  servo: [
    step('servo-signal', 'Send position instructions on GPIO18', 'Connect GPIO18 to the servo’s signal wire. The sketch sends pulses whose width requests a target position. This wire carries the instruction; it does not supply the motor’s movement current. Check the servo’s connector and wire colors.', ['pin:18', 'component:servo'], 'connection', 0),
    step('servo-power', 'Power the movement from a suitable supply', 'Connect the servo’s positive power wire to a regulated external supply that matches its rating, often 5 V for an SG90. The supply must handle movement current. Do not power the servo from an ESP32 GPIO or the 3V3 pin.', ['component:supply', 'component:servo'], 'connection', 1),
    step('servo-ground', 'Join both grounds', 'Connect servo ground and the external supply’s ground to ESP32 GND. This gives the position pulses a shared voltage reference. A separate positive supply still needs this ground connection for the control signal to make sense.', ['component:servo', 'component:supply', 'pin:GND'], 'connection', 2),
    step('servo-try', 'Choose a safe target', 'Run the simulation and drag the horn to choose an angle. The readout is the requested target, not measured feedback. On hardware, begin with a conservative range and stop before mechanical limits; never force the horn against its gears.', ['component:servo', 'pin:18'], 'circuit')
  ],
  stepper: [
    step('stepper-first', 'Connect the first driver inputs', 'Connect GPIO16 and GPIO17 to the ULN2003 board’s IN1 and IN2. These are low-current control signals. GPIO16 may be labeled RX2 and GPIO17 TX2 on this DevKit; the sketch uses their GPIO numbers.', ['pin:16', 'pin:17', 'component:driver'], 'connection', 0),
    step('stepper-second', 'Connect the remaining inputs', 'Connect GPIO18 and GPIO19 to IN3 and IN4. Four inputs let the driver energize coils in sequence. Keep the wiring order shown here; the example’s Stepper constructor deliberately lists pins in a 1-3-2-4 sequence.', ['pin:18', 'pin:19', 'component:driver'], 'connection', 1),
    step('stepper-power', 'Power the driver and share ground', 'For the 5 V version of the 28BYJ-48, connect a suitable external 5 V supply to driver positive and ground to driver negative. Join that ground to ESP32 GND. The driver supplies coil current; GPIO pins do not.', ['component:supply', 'component:driver', 'pin:GND'], 'connection', 2),
    step('stepper-plug', 'Plug the motor into its driver', 'The motor’s five-wire connector plugs into the matching ULN2003 socket. The driver sits between the ESP32’s small control signals and the motor coils. Do not replace this connection by attaching the motor wires straight to GPIO pins.', ['component:stepper', 'component:driver'], 'connection', 3),
    step('stepper-try', 'Count a relative movement', 'Run the simulation and tap the stepper to advance its target by 45°. The hardware sketch moves relative to its current starting position. Resetting or uploading makes it move again; it does not return to a known home position. It cannot detect missed steps without feedback.', ['component:stepper', 'component:driver'], 'circuit')
  ],
  plant: [
    step('plant-sensor-power', 'Power a compatible moisture sensor', 'Use a capacitive sensor rated for 3.3 V operation. Connect its VCC to 3V3 and its GND to board ground. This supplies the sensor while keeping its output suitable for the ESP32 input. Keep its electronics above the soil and out of water.', ['pin:3V3', 'pin:GND', 'component:soil'], 'connection', 0),
    step('plant-analog', 'Read the sensor’s analog output', 'Connect the sensor’s analog-output terminal to GPIO34. This input-only pin measures voltage, not moisture directly. The sketch turns your measured dry and wet reference values into a relative percentage, so calibration is part of making the reading useful.', ['component:soil', 'pin:34'], 'connection', 1),
    step('plant-bus', 'Send display data over two wires', 'Connect GPIO21 to OLED SDA and GPIO22 to OLED SCL. SDA carries data; SCL carries the clock that times it. These two I²C signal wires let the sketch send text and graphics to the display.', ['pin:21', 'pin:22', 'component:oled'], 'connection', 2),
    step('plant-display-power', 'Power the screen as well as its signals', 'A 3.3 V-compatible OLED also needs VCC connected to 3V3 and GND to ground. SDA and SCL alone do not power it. Verify the module’s I²C address, commonly 0x3C, if the screen stays blank.', ['pin:3V3', 'pin:GND', 'component:oled'], 'connection', 3),
    step('plant-try', 'Follow sensing through to the screen', 'Run the simulation and tap the soil or OLED to change simulated moisture. The reading is mapped to a relative scale, then used to choose the message. Real soil does not respond instantly, and the percentage is not an absolute measurement of water content.', ['component:soil', 'component:oled', 'pin:34'], 'circuit')
  ],
  force: [
    step('force-upper', 'Let pressure change a resistance', 'Connect the force-sensing resistor, or FSR, between 3V3 and the GPIO34 junction. Pressing its pad lowers its resistance. The 3V3 pin supplies this circuit; GPIO34 measures the junction voltage and cannot drive an output.', ['pin:3V3', 'component:fsr', 'pin:34'], 'connection', 0),
    step('force-lower', 'Turn resistance into voltage', 'Connect 10 kΩ between the GPIO34 junction and GND. Together, the FSR and this resistor form a divider. More pressure lowers the upper resistance, so the junction voltage rises. Without this lower path, the intended measurement circuit is incomplete.', ['pin:34', 'component:resistor:10k', 'pin:GND'], 'connection', 1),
    step('force-output', 'Show the input with an LED', 'Connect GPIO23 through a 330 Ω resistor and LED to GND. The sketch maps the input reading to PWM brightness. The 330 Ω LED resistor and the 10 kΩ sensor resistor perform different jobs and should not be swapped.', ['pin:23', 'component:resistor:330', 'component:led', 'pin:GND'], 'connection', 2),
    step('force-try', 'Apply, then remove, pressure', 'Run the simulation and hold the pad. The illustrated reading and LED brightness rise; releasing removes the force. Treat the reading as relative pressure: contact area and mounting affect a real FSR, so an uncalibrated ADC value is not a measurement in newtons.', ['component:fsr', 'component:led', 'pin:34'], 'circuit')
  ],
  wifi: [
    step('wifi-output', 'Start with a familiar LED output', 'Connect GPIO23 through 330 Ω to the LED anode. The resistor still limits current, exactly as in the blink lesson. Wireless control changes where the instruction comes from; the LED still needs a correctly wired output circuit.', ['pin:23', 'component:resistor:330', 'component:led'], 'connection', 0),
    step('wifi-ground', 'Complete the LED circuit', 'Connect the LED cathode to ESP32 GND. A wireless message cannot replace this electrical return path. GPIO23 goes HIGH or LOW according to the request handler, and current can flow only through the complete LED circuit.', ['component:led', 'pin:GND'], 'connection', 1),
    step('wifi-usb', 'Upload through USB first', 'Connect a data-capable Micro-USB cable to upload the sketch and power the board. The ESP32 then creates its own local Wi-Fi network. USB is for initial programming and power here; your phone’s later control requests arrive by radio.', ['part:usb', 'part:module'], 'usb', 2),
    step('wifi-network', 'Join the board’s local network', 'After uploading to real hardware, join ESP32-Lab on your phone and open http://192.168.4.1. The page is served by the ESP32 itself, so this connection does not need internet access. Keep the phone connected when it reports “no internet”.', ['part:antenna', 'part:module'], 'board'),
    step('wifi-try', 'Turn a request into a pin change', 'Run the browser simulation and tap the LED to send a virtual on/off request. On hardware, the page requests /on or /off and the ESP32 changes GPIO23. This website demonstrates that chain locally; it does not automatically connect to your physical board.', ['part:antenna', 'pin:23', 'component:led'], 'circuit')
  ]
};
